#!/usr/bin/env node
/*
 * Grade9v3.5 #183 / r7 — SOURCE-SAFE, PRIVATE A4 QA from the native page.
 *
 * Reuses the actual HTML already generated by Shared/tools/render_core.py.
 * Does NOT compose/rewrite HTML, publish a PDF, alter print-product.mjs,
 * materialise protected answer templates or make an Owner print decision.
 *
 * node TEST/imo-research/core2-q003/audit_private_a4.mjs
 * node TEST/imo-research/core2-q003/audit_private_a4.mjs --include-core2
 *
 * Requires Playwright + its Chromium binary; no pdfinfo/Poppler or new
 * dependency is needed. Everything stays in .private/a4-audit.
 */
import { createRequire } from 'node:module';
import { execFileSync } from 'node:child_process';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const privateRoot = path.join(here, '.private');
const auditRoot = path.join(privateRoot, 'a4-audit');
const args = process.argv.slice(2);
const accepted = new Set(['--include-core2']);
if (args.some(arg => !accepted.has(arg)) || args.length !== new Set(args).size) {
  console.error('Usage: node audit_private_a4.mjs [--include-core2]');
  process.exit(2);
}

const sha256 = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const within = (child, ancestor) => {
  const rel = path.relative(ancestor, child);
  return !!rel && !rel.startsWith('..' + path.sep) && rel !== '..' && !path.isAbsolute(rel);
};
const insist = (condition, message) => {
  if (!condition) throw new Error(message);
};

const cases = [
  {
    role: 'CORE1A',
    page: path.join(privateRoot, 'core1a', 'rendered', 'core1a.html'),
    sha256: 'd1fe23c43d1eeae67c69600beef1b5054c361854c3e5cd6742545859592998c0',
    bytes: 76401,
    blueprint: 'BP-CORE1A-CONSTRUCTION',
  },
];
if (args.includes('--include-core2')) {
  cases.push({
    role: 'CORE2',
    page: path.join(privateRoot, 'rendered', 'core2.html'),
    sha256: '827a8a99128601721c3c13dfd99806b5a563624526edfd8ba137ab8d4b64b6a0',
    bytes: 62277,
    blueprint: 'BP-CORE2-SOURCE-QUESTION',
  });
}

let playwright;
try {
  const require = createRequire(import.meta.url);
  try { playwright = require('playwright'); }
  catch {
    const globalNpmRoot = execFileSync('npm', ['root', '-g'], { encoding: 'utf8' }).trim();
    playwright = require(path.join(globalNpmRoot, 'playwright'));
  }
} catch {
  console.error('A4_AUDIT_BLOCKED: Playwright is not locally installed; no substitute HTML/PDF produced.');
  process.exit(2);
}

const pdfGeometry = pdf => {
  // No Poppler install: traverse Chromium's PDF page tree, count each leaf and
  // verify EVERY leaf MediaBox. Reject unrecognised structures, never guess.
  const fail = code => { throw new Error(code); };
  if (!Buffer.isBuffer(pdf) || pdf.subarray(0, 5).toString('ascii') !== '%PDF-')
    fail('PDF_HEADER_INVALID');
  const text = pdf.toString('latin1');
  if (!/%%EOF\s*$/.test(text.slice(-1024))) fail('PDF_EOF_MISSING');
  const objects = new Map();
  const objectPattern = /(?:^|[\r\n])(\d+)\s+(\d+)\s+obj\b([\s\S]*?)\bendobj\b/g;
  for (const match of text.matchAll(objectPattern)) {
    const key = match[1] + ':' + match[2];
    if (objects.has(key)) fail('PDF_OBJECT_DUPLICATED');
    objects.set(key, match[3].split(/\bstream\r?\n/, 1)[0]);
  }
  const get = (id, generation) => {
    const object = objects.get(id + ':' + generation);
    if (!object) fail('PDF_PAGE_OBJECT_UNRESOLVED');
    return object;
  };
  const catalogue = [...objects.entries()].filter(([, o]) => /\/Type\s*\/Catalog\b/.test(o));
  if (catalogue.length !== 1) fail('PDF_CATALOGUE_NOT_UNIQUE');
  const root = catalogue[0][1].match(/\/Pages\s+(\d+)\s+(\d+)\s+R\b/);
  if (!root) fail('PDF_PAGE_TREE_MISSING');
  const boxes = [];
  const visited = new Set();
  const parseBox = object => {
    const value = object.match(/\/MediaBox\s*\[\s*([-+]?\d*\.?\d+)\s+([-+]?\d*\.?\d+)\s+([-+]?\d*\.?\d+)\s+([-+]?\d*\.?\d+)\s*\]/);
    return value ? value.slice(1).map(Number) : null;
  };
  const walk = (id, gen, inheritedBox, parentKey = null) => {
    const key = id + ':' + gen;
    if (visited.has(key)) fail('PDF_PAGE_TREE_REPEATED_OR_CYCLIC');
    visited.add(key);
    const object = get(id, gen);
    if (parentKey) {
      const parent = object.match(/\/Parent\s+(\d+)\s+(\d+)\s+R\b/);
      if (!parent || parent[1] + ':' + parent[2] !== parentKey)
        fail('PDF_PAGE_PARENT_MISMATCH');
    }
    const rotate = object.match(/\/Rotate\s+(-?\d+)\b/);
    if (rotate && Number(rotate[1]) % 360 !== 0) fail('PDF_PAGE_ROTATED');
    const box = parseBox(object) || inheritedBox;
    if (/\/Type\s*\/Pages\b/.test(object)) {
      const kidsMatch = object.match(/\/Kids\s*\[([^\]]*)\]/);
      const declared = object.match(/\/Count\s+(\d+)\b/);
      if (!kidsMatch || !declared) fail('PDF_PAGE_TREE_MALFORMED');
      const kidRegex = /(\d+)\s+(\d+)\s+R\b/g;
      const kids = [...kidsMatch[1].matchAll(kidRegex)].map(m => [m[1], m[2]]);
      if (!kids.length || kidsMatch[1].replace(kidRegex, '').trim())
        fail('PDF_PAGE_KIDS_MALFORMED');
      const observed = kids.reduce((sum, [child, generation]) =>
        sum + walk(child, generation, box, key), 0);
      if (Number(declared[1]) !== observed) fail('PDF_PAGE_COUNT_MISMATCH');
      return observed;
    }
    if (!/\/Type\s*\/Page\b/.test(object)) fail('PDF_NON_PAGE_IN_PAGE_TREE');
    if (!box || box.some(x => !Number.isFinite(x))) fail('PDF_MEDIA_BOX_MISSING');
    const width = box[2] - box[0], height = box[3] - box[1];
    if (!(width > 0 && height > 0)) fail('PDF_MEDIA_BOX_INVALID');
    boxes.push([width, height]);
    return 1;
  };
  const total = walk(root[1], root[2], null);
  const allLeafPages = [...objects.values()].filter(o => /\/Type\s*\/Page\b/.test(o)).length;
  if (total < 1 || total !== boxes.length || total !== allLeafPages)
    fail('PDF_PAGE_COUNT_INCONSISTENT');
  const [widthPt, heightPt] = boxes[0];
  const a4 = boxes.every(([w, h]) => Math.abs(w - 595.276) < 1.5 &&
                                     Math.abs(h - 841.890) < 1.5);
  return {
    page_count: total,
    paper_size_pt: [widthPt, heightPt],
    paper_size_mm: [Math.round(widthPt * 25.4 / 72 * 10) / 10,
                    Math.round(heightPt * 25.4 / 72 * 10) / 10],
    a4_portrait_geometry: a4,
    geometry_method: 'PDF_PAGE_TREE_ALL_LEAF_MEDIABOXES_NODE_BUILTIN',
  };
};

fs.mkdirSync(auditRoot, { recursive: true, mode: 0o700 });
insist(within(auditRoot, privateRoot), 'OUTPUT_NOT_PRIVATE');

let browser;
const entries = [];
try {
  try { browser = await playwright.chromium.launch(); }
  catch { throw new Error('PLAYWRIGHT_CHROMIUM_UNAVAILABLE'); }
  const context = await browser.newContext({ viewport: { width: 794, height: 1123 } });
  await context.route(/^https?:\/\//, route => route.abort('blockedbyclient'));
  const page = await context.newPage();
  for (const item of cases) {
    insist(within(item.page, privateRoot), 'PAGE_NOT_PRIVATE');
    insist(fs.existsSync(item.page), 'EXACT_NATIVE_PAGE_NOT_FOUND_' + item.role);
    const htmlBytes = fs.readFileSync(item.page);
    insist(htmlBytes.length === item.bytes && sha256(htmlBytes) === item.sha256,
           'EXACT_NATIVE_PAGE_SHA_MISMATCH_' + item.role);
    const receiptFile = path.join(path.dirname(item.page), 'render-receipt.json');
    insist(fs.existsSync(receiptFile), 'NATIVE_RENDER_RECEIPT_MISSING_' + item.role);
    const renderReceipt = JSON.parse(fs.readFileSync(receiptFile, 'utf8'));
    insist(renderReceipt.renderer === 'render_core/2' &&
           Array.isArray(renderReceipt.gaps) && renderReceipt.gaps.length === 0 &&
           Array.isArray(renderReceipt.pages) && renderReceipt.pages.includes(path.basename(item.page)),
           'NATIVE_RENDER_RECEIPT_NOT_ZERO_GAP_' + item.role);

    await page.goto(pathToFileURL(item.page).href, { waitUntil: 'load' });
    const printGuard = await page.evaluate(expected => {
      const root = document.documentElement;
      const protectedReveals = [...document.querySelectorAll('details[data-requires-attempt]')];
      const revealedCount = protectedReveals.filter(d => d.open).length;
      return {
        role_matches: root.getAttribute('data-g9-role') === expected.role,
        blueprint_matches: document.body.getAttribute('data-blueprint-ref')?.startsWith(expected.blueprint + '@') ?? false,
        protected_reveals_open: revealedCount,
        source_payload_templates: document.querySelectorAll('template[data-g9-payload]').length,
      };
    }, { role: item.role, blueprint: item.blueprint });
    insist(printGuard.role_matches && printGuard.blueprint_matches,
           'WRONG_NATIVE_ROLE_OR_BLUEPRINT_' + item.role);
    await page.emulateMedia({ media: 'print' });
    const hiddenAfterPrintCss = await page.evaluate(() =>
      [...document.querySelectorAll('details[data-requires-attempt]')]
        .every(d => !d.open && getComputedStyle(d).display === 'none')
    );
    insist(hiddenAfterPrintCss && printGuard.protected_reveals_open === 0,
           'PROTECTED_REVEAL_VISIBLE_BEFORE_PRINT_' + item.role);

    const pdf = await page.pdf({
      format: 'A4', preferCSSPageSize: false, landscape: false,
      printBackground: true, displayHeaderFooter: false,
      margin: { top: '10mm', bottom: '10mm', left: '10mm', right: '10mm' },
    });
    const pdfName = item.role.toLowerCase() + '-native-a4.private.pdf';
    const pdfPath = path.join(auditRoot, pdfName);
    insist(within(pdfPath, privateRoot), 'PDF_OUTPUT_NOT_PRIVATE');
    const geometry = pdfGeometry(pdf);
    insist(geometry.a4_portrait_geometry, 'PRINT_PDF_NOT_A4_' + item.role);
    fs.writeFileSync(pdfPath, pdf, { mode: 0o600 });
    insist(sha256(fs.readFileSync(item.page)) === item.sha256, 'NATIVE_PAGE_CHANGED_DURING_PRINT_' + item.role);
    entries.push({
      role: item.role,
      source_page_sha256: item.sha256, source_page_bytes: item.bytes,
      native_renderer: renderReceipt.renderer, native_gaps: 0,
      printed_pdf_sha256: sha256(pdf), printed_pdf_bytes: pdf.length,
      pdf_private_basename: pdfName,
      ...geometry,
      protected_reveal_visible_before_print: false,
      source_payload_template_count: printGuard.source_payload_templates,
      protected_template_materialised_by_audit: false,
      content_clipping_and_print_legibility: 'NOT_VISUALLY_REVIEWED',
      owner_same_page_a4_accepted: false,
    });
    await page.emulateMedia({ media: 'screen' });
  }
  const report = {
    schema: 'q003-native-page-private-a4-audit/v1',
    issue: 183, tasks: ['183-T5-G2-W1'], aim: 'v3.1.0',
    source_page_test_commit: 'f030a0aca51038575778de3489f75d1d629a6b74',
    audit_tool: 'TEST/imo-research/core2-q003/audit_private_a4.mjs',
    method: 'PRIVATE_NATIVE_HTML_THROUGH_PLAYWRIGHT_A4_PRINT_NOT_SHARED_PRODUCTION_PDF',
    browser: browser.version(), print_pdf_format: 'A4',
    output_scope: 'IGNORED_PRIVATE_OPERATOR_MACHINE_ONLY',
    canonical_print_product_uses_280x175mm: true,
    pages: entries, keyboard_accessibility: 'DEFERRED_BY_USER',
    owner_visual_approval: 'PENDING', publisher_rights_granted: false,
    owner_qrt_accepted: false, published: false,
    status: 'A4_PDF_GEOMETRY_VERIFIED_ONLY_OWNER_PRINT_REVIEW_PENDING',
  };
  fs.writeFileSync(path.join(auditRoot, 'source-safe-a4-audit-receipt.json'),
                   JSON.stringify(report, null, 2) + '\n',
                   { mode: 0o600 });
  console.log('A4_AUDIT_GEOMETRY_VERIFIED_ONLY; owner same-page A4 inspection remains PENDING');
  console.log('source-safe receipt: TEST/imo-research/core2-q003/.private/a4-audit/source-safe-a4-audit-receipt.json');
} catch (error) {
  // Never emit source HTML, PDF bytes, question stems or source-dependent text.
  const knownCode = String(error.message || 'AUDIT_ERROR');
  const safeCode = /^[A-Z0-9_]+$/.test(knownCode) ? knownCode : 'LOCAL_A4_AUDIT_FAILED';
  console.error('A4_AUDIT_BLOCKED: ' + safeCode);
  process.exitCode = 1;
} finally {
  if (browser) await browser.close();
}
